```openscad
// Round-bottom flask support ring on three legs
// Print orientation: legs stand on the bed (z = 0), ring on top

$fn = 96;

// --- Ring ---
ring_od      = 80;   // ring outer diameter
ring_id      = 60;   // ring inner diameter
ring_t       = 5;    // ring thickness
ring_top_z   = 60;   // height of ring top face

// --- Legs ---
leg_d        = 6;    // leg diameter
leg_pcd      = 70;   // diameter of circle the leg axes lie on
leg_count    = 3;    // number of legs
leg_start    = 0;    // angle of first leg (deg, +X axis)

// --- Helpers ---
eps          = 0.5;  // overshoot for boolean cuts
overlap      = 0.5;  // leg embeds into ring for a solid union

ring_bot_z   = ring_top_z - ring_t;

union() {
    // Flat annular ring
    translate([0, 0, ring_bot_z])
        difference() {
            cylinder(d = ring_od, h = ring_t);
            translate([0, 0, -eps])
                cylinder(d = ring_id, h = ring_t + 2 * eps);
        }

    // Legs from bed up into the ring
    for (i = [0 : leg_count - 1]) {
        a = leg_start + i * 360 / leg_count;
        translate([leg_pcd / 2 * cos(a), leg_pcd / 2 * sin(a), 0])
            cylinder(d = leg_d, h = ring_bot_z + overlap);
    }
}
