ring_id        = 44;   // inner diameter of ring (mm)
ring_thick     = 6;    // ring thickness (mm)
ring_top_z     = 50;   // z height of ring top face (mm)
ring_bottom_z  = ring_top_z - ring_thick; // z height of ring bottom face

