// Spacer for raising a circuit board, with counterbore for a socket-head screw
// Print orientation: standing on the bed, z = 0 to 12, centred on origin

$fn = 96;

// --- Dimensions (mm) ---
body_d     = 24;    // outer diameter of spacer
body_h     = 12;    // total height of spacer
hole_d     = 5.5;   // through-hole diameter (screw shank clearance)
cbore_d    = 10;    // counterbore diameter (screw head)
cbore_depth = 4;    // counterbore depth from top face (z = 8 to 12)

eps = 0.5;          // overcut so cutting faces are not coplanar

difference() {
    // Main body
    cylinder(d = body_d, h = body_h);

    // Through hole along the axis
    translate([0, 0, -eps])
        cylinder(d = hole_d, h = body_h + 2 * eps);

    // Counterbore from the top face
    translate([0, 0, body_h - cbore_depth])
        cylinder(d = cbore_d, h = cbore_depth + eps);
}
```

