```openscad
// Sliding mount: flat base plate with a full-length dovetail rail
// Print orientation: plate flat on the bed (z = 0), rail building upward (+Z)

// ---------------- Parameters (mm) ----------------
plate_len      = 80;    // base plate length (X)
plate_wid      = 30;    // base plate width (Y)
plate_thk      = 4;     // base plate thickness (Z), z = 0..4

rail_bot_wid   = 12;    // dovetail width where it meets the plate (z = 4)
rail_top_wid   = 16;    // dovetail width at its top face (z = 9)
rail_top_z     = 9;     // absolute Z of rail top face
rail_len       = plate_len; // rail runs the full plate length

overlap        = 0.01;  // small overlap so rail fuses into plate (no coplanar faces)

$fn = 64;

// ---------------- Derived ----------------
rail_h      = rail_top_z - plate_thk;                       // rail height (5 mm)
flare       = (rail_top_wid - rail_bot_wid) / 2 / rail_h;   // half-width growth per mm of height
bot_half_ov = rail_bot_wid / 2 - flare * overlap;           // half-width at z = plate_thk - overlap

// ---------------- Model ----------------
union() {
    // Base plate, centred in X and Y
    translate([-plate_len / 2, -plate_wid / 2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Dovetail rail: trapezoid profile drawn in YZ, extruded along X
    // rotate([90,0,90]) maps 2D x -> Y, 2D y -> Z, extrusion -> X
    rotate([90, 0, 90])
        linear_extrude(height = rail_len, center = true)
            polygon(points = [
                [-bot_half_ov,      plate_thk - overlap],
                [ bot_half_ov,      plate_thk - overlap],
                [ rail_top_wid / 2, rail_top_z],
                [-rail_top_wid / 2, rail_top_z]
            ]);
}
```

