```openscad
// Sliding mount with dovetail rail
// Print orientation: base plate on the bed (z = 0), rail on top, centred on origin in X/Y.

$fn = 64;

// ---------------- Base plate ----------------
plate_len   = 100;   // plate length along X
plate_wid   = 30;    // plate width along Y
plate_thk   = 6;     // plate thickness (z = 0 to 6)

// ---------------- Dovetail rail ----------------
rail_len      = plate_len; // rail runs the full length of the plate
rail_w_bottom = 8;         // rail width where it meets the plate (z = 6)
rail_w_top    = 14;        // rail width at its top face (z = 14)
rail_top_z    = 14;        // z of rail top face
rail_h        = rail_top_z - plate_thk; // rail height (8 mm)

// ---------------- Misc ----------------
overlap = 0.01;            // small overlap so rail fuses into plate (no coplanar faces)

// Rail width at the overlap depth (extrapolated along the flank so the profile stays true)
flare_per_mm      = (rail_w_top - rail_w_bottom) / rail_h;   // width increase per mm height
rail_w_overlap    = rail_w_bottom - flare_per_mm * overlap;  // width at z = plate_thk - overlap

module base_plate() {
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);
}

module dovetail_rail() {
    // 2D profile: 2D x -> world Y, 2D y -> world Z; extrusion -> world X
    rotate([90, 0, 90])
        linear_extrude(height = rail_len, center = true)
            polygon(points = [
                [-rail_w_overlap/2, plate_thk - overlap],
                [ rail_w_overlap/2, plate_thk - overlap],
                [ rail_w_top/2,     rail_top_z],
                [-rail_w_top/2,     rail_top_z]
            ]);
}

union() {
    base_plate();
    dovetail_rail();
}
