```openscad
// Sliding mount with dovetail rail
// Print orientation: base plate flat on the bed, rail pointing up (+Z)

$fn = 64;

// ---------- Base plate ----------
plate_len   = 80;   // plate length along X
plate_wid   = 40;   // plate width along Y
plate_thk   = 4;    // plate thickness (z = 0 .. 4)

// ---------- Dovetail rail ----------
rail_len     = plate_len; // rail runs the full plate length
rail_w_base  = 10;  // rail width where it meets the plate (z = 4)
rail_w_top   = 16;  // rail width at its top face (z = 9)
rail_top_z   = 9;   // absolute Z of the rail's top face
rail_h       = rail_top_z - plate_thk; // rail height (5 mm)

overlap      = 0.01; // small embed of rail into plate for a clean union

// Half-width of the rail at the slightly embedded bottom (follows the same flank slope)
half_slope   = (rail_w_top - rail_w_base) / 2 / rail_h;   // dY per dZ on each flank
rail_w_embed = rail_w_base - 2 * half_slope * overlap;

module base_plate() {
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);
}

module dovetail_rail() {
    // Profile drawn in 2D with 2D-x = world Y and 2D-y = world Z,
    // then extruded and rotated so the extrusion runs along world X.
    rotate([90, 0, 90])
        linear_extrude(height = rail_len, center = true)
            polygon([
                [-rail_w_embed/2, plate_thk - overlap],
                [ rail_w_embed/2, plate_thk - overlap],
                [ rail_w_top/2,   rail_top_z],
                [-rail_w_top/2,   rail_top_z]
            ]);
}

union() {
    base_plate();
    dovetail_rail();
}
