flare        = (rail_w_top - rail_w_base) / 2 / rail_h;     // half-width growth per mm of Z
w_overlap    = rail_w_base - 2 * flare * overlap;           // width at z = plate_thk - overlap (keeps flank slope)

// ---------------- Model ----------------
union() {
    // Base plate
    translate([-plate_len/2, -plate_wid/2, 0])
        cube([plate_len, plate_wid, plate_thk]);

    // Dovetail rail: trapezoid in YZ, extruded along X
    translate([-rail_len/2, 0, 0])
        rotate([90, 0, 90])            // 2D x -> Y, 2D y -> Z, extrude -> +X
            linear_extrude(height = rail_len)
                polygon(points = [
                    [-w_overlap/2,  plate_thk - overlap],
                    [ w_overlap/2,  plate_thk - overlap],
                    [ rail_w_top/2, rail_top_z],
                    [-rail_w_top/2, rail_top_z]
                ]);
}
