// V-groove cutter: triangle profile in XZ, extruded along Y.
// The sides are extended above the top face so the 90-degree angle is kept
// and no faces are coplanar.
module v_groove() {
    half_top = groove_top_w / 2 + cut_extra;  // keeps 45-degree flanks
    rotate([90, 0, 0])
        linear_extrude(height = block_wid + 2 * cut_extra, center = true)
            polygon([
                [-half_top, block_ht + cut_extra],
                [ half_top, block_ht + cut_extra],
                [ 0,        block_ht - groove_depth]
            ]);
}

difference() {
    // Main block, centred in X and Y, sitting on z = 0
    translate([-block_len / 2, -block_wid / 2, 0])
        cube([block_len, block_wid, block_ht]);

    // Row of grooves centred along X
    for (i = [0 : groove_count - 1])
        translate([(i - (groove_count - 1) / 2) * groove_pitch, 0, 0])
            v_groove();
}
