// Stepped riser: 4-step solid staircase climbing in +X
// Placed at the user-specified coordinates: x = 0..40, y = 0..30, z = 0..40

// ---- Parameters ----
num_steps   = 4;    // number of steps
step_length = 10;   // length of each step along X (mm)
step_rise   = 10;   // height increase per step (mm)
depth       = 30;   // extrusion depth along Y (mm)

total_length = num_steps * step_length; // overall X length (40 mm)

// ---- Model ----
// Each block starts at its step's X position and runs to the far end,
// so the blocks overlap instead of only touching at shared faces.
union() {
    for (i = [0 : num_steps - 1]) {
        translate([i * step_length, 0, 0])
            cube([total_length - i * step_length,  // run to the end (overlapping)
                  depth,
                  (i + 1) * step_rise]);            // step height: 10, 20, 30, 40
    }
}
