// Stepped riser - solid staircase of 4 equal steps
// Profile drawn in XZ, climbing in +X, extruded along +Y from y = 0 to y = 30

// ---------------- Parameters ----------------
num_steps   = 4;    // number of steps
step_len    = 12;   // length of each step in X (mm)
step_rise   = 8;    // height increase per step in Z (mm)
depth_y     = 30;   // extrusion depth along Y (mm)

total_len    = num_steps * step_len;   // 48 mm overall length in X
total_height = num_steps * step_rise;  // 32 mm top step height

$fn = 64; // no curved features, set per guidelines

// ---------------- Profile ----------------
// Staircase outline (x, z): along the bed, up the back face,
// then down each step from the top back to the front edge.
function stair_profile() = concat(
    [[0, 0], [total_len, 0]],
    [for (i = [num_steps - 1 : -1 : 0])
        each [[(i + 1) * step_len, (i + 1) * step_rise],
              [i * step_len,       (i + 1) * step_rise]]]
);

// ---------------- Model ----------------
// Extrude the 2D profile along local Z, then rotate so local Z maps to -Y,
// and shift by depth_y so the part spans y = 0 to y = 30.
translate([0, depth_y, 0])
    rotate([90, 0, 0])
        linear_extrude(height = depth_y)
            polygon(points = stair_profile());
