riser_depth = 20;   // extrusion depth along Y (mm)
$fn = 64;           // not used (no curves), kept per convention

// Each step is solid down to the bed: step i spans x = i*step_len .. (i+1)*step_len,
// height (i+1)*step_rise. Neighbouring blocks overlap slightly so the union is one solid.
overlap = 0.01;

