    translate([-base_x/2, -base_y/2, 0])
        cube([base_x, base_y, wall_h + eps]);

    // Chamfered top: frustum from full footprint to reduced top face
    hull() {
        translate([-base_x/2, -base_y/2, wall_h])
            cube([base_x, base_y, eps]);
        translate([-(base_x - 2*chamfer)/2, -(base_y - 2*chamfer)/2, base_h - eps])
            cube([base_x - 2*chamfer, base_y - 2*chamfer, eps]);
